  'vt.ineq.short': '用＜＞提示大小', 'vt.antiknight.short': '马步位置不重复', 'vt.kropki.short': '白点表示连续', 'vt.thermo.short': '沿温度计逐渐变大', 'vt.arrow.short': '圆圈＝箭头之和',
